// Two bars: share of patients called in the month who came back within 30 days, by when the call was made.
const one = (n) => { const v = col(n)[0]; return v === null || v === undefined || v === '' ? null : Number(v); };
const C = chartColors;
const rv = context.grafana && context.grafana.replaceVariables;
const allowed = !rv || rv('${isAllowed}') === '1';
const centre = (text) => ({ graphic: allowed ? [{ type: 'text', left: 'center', top: 'middle', style: { text: text, fontSize: 14, fill: C.muted } }] : [] });
if (!col('called_month_n').length) { return centre('No data for this place.'); }
const K = one('called_month_n') || 0, R = one('returned_month_n') || 0, pe = one('returned_early_pct'), pl = one('returned_later_pct');
const E = one('early_n') || 0, open = one('return_open_n') || 0, days = one('early_days');
if (!K) { return centre('No calls this month.'); }
// Counts behind the two shares: early calls are early_n of called_n; the rest are later.
const re = pe === null ? 0 : Math.round(pe * E / 100);
const nOf = [[re, E], [R - re, K - E]];
const share = [pe, pl];
const pctTxt = (v) => (v === null ? '—' : (Math.abs(v) < 10 ? v.toFixed(1) : String(Math.round(v))) + '%');
const names = ['Called within ' + fmt(days) + ' days', 'Called later'];
const label = (k) => (share[k] === null ? 'No calls' : pctTxt(share[k]) + ' · ' + fmt(nOf[k][0]) + ' of ' + fmt(nOf[k][1]));
return {
  animation: false,
  grid: { left: 8, right: 120, top: 8, bottom: open ? 40 : 16, containLabel: true },
  tooltip: tip((k) => [share[k] === null ? 'No calls in this group' : fmt(nOf[k][0]) + ' of ' + fmt(nOf[k][1]) + ' came back (' + pctTxt(share[k]) + ')'],
    (k) => names[k], { axisPointer: { type: 'shadow', shadowStyle: { color: 'rgba(110,127,141,0.12)' } } }),
  yAxis: { type: 'category', inverse: true, data: names, axisTick: { show: false },
    axisLabel: { color: C.text, fontSize: 13 }, axisLine: { lineStyle: { color: C.axisLine } } },
  xAxis: { type: 'value', min: 0, max: 100, interval: 25, axisLabel: { color: C.axis, fontSize: 11, formatter: (v) => v + '%' },
    splitLine: { lineStyle: { color: C.grid } } },
  series: [{
    type: 'bar', name: 'Came back', barWidth: '46%',
    data: share.map((v, k) => ({ value: v === null ? 0 : v, itemStyle: { color: k ? C.step[1] : C.step[4], borderRadius: [0, 2, 2, 0] } })),
    label: { show: true, position: 'right', color: C.text, fontSize: 12, formatter: (p) => label(p.dataIndex) }
  }],
  graphic: open ? [{ type: 'text', left: 8, bottom: 8, style: { text: fmt(open) + ' called patients have not come back yet. They may still come back.', fontSize: 12, fill: C.muted } }] : []
};

