const { overdueHref } = rpt;
// Side card (UX-08): what happened on the calls, then a plan one nurse can do. The total is context, not
// the target. Same plan as the chat (h360_api ranker CONSTANTS: calls_per_nurse_week 25, plan_weeks 4).
const root = rpt.mount('.rpt-cal-calls');
if (!root) { return; }
rpt.wireScroll(root);
const { esc, fmt, num } = rpt;
const r = rpt.rows('A')[0];
const PER_NURSE = 25, WEEKS = 4;
const here = rpt.atFacility();
const open = here ? '<a class="rpt-link" href="' + esc(overdueHref(rpt.orgUnit())) + '">Open the overdue list →</a>'
  : '<a class="rpt-link" href="#rpt-cal-table">Pick a facility to open its list →</a>';
const head = '<h3 class="rpt-card-title">What happened on the calls</h3>';
if (!r) { root.innerHTML = head + rpt.noData() + open; return; }
const li = (label, n) => '<li><span>' + esc(label) + '</span><span>' + fmt(n) + '</span></li>';
const N = num(r.called_n) || 0, overdue = num(r.overdue_with_phone_n) || 0;
const facilities = here ? 1 : Math.max(1, num(r.facilities_n) || 0);
const plan = Math.min(PER_NURSE * WEEKS * facilities, overdue);
const planLine = facilities > 1
  ? 'One nurse per facility can call about ' + PER_NURSE + ' a week, so ' + fmt(plan) + ' in ' + WEEKS + ' weeks across ' + fmt(facilities) + ' facilities.'
  : 'One nurse can call about ' + PER_NURSE + ' a week, so ' + fmt(plan) + ' in ' + WEEKS + ' weeks.';
root.innerHTML = head
  + '<ul class="rpt-kv">' + li('Agreed to visit', r.agreed_n) + li('Call again later', r.call_again_n) + li('Removed from list', r.removed_n) + '</ul>'
  + '<div class="rpt-kv-total">' + fmt(N) + (N === 1 ? ' patient' : ' patients') + ' called in ' + esc(rpt.month(rpt.reportingMonth())) + '</div>'
  + '<h3 class="rpt-card-title rpt-plan">A plan you can do</h3>'
  + '<div class="rpt-line rpt-plan-do">' + esc(planLine) + ' Start at the top of the list, with patients not called yet.</div>'
  + '<div class="rpt-line">' + fmt(overdue) + ' overdue patients have a phone.</div>'
  + open;

